/// <summary>
/// MPJ_3747_AltVendorPayee 06/03/2021 Nathan Ciantar
/// returns the field found
/// </summary>
/// <returns>metOrganisation</returns>
public display METOrganisation displayMETOrganisation()
{
    return VendBankAccount::find(this.AccountNum, this.BankAccount).METVendorBankOrganisation;
}

/// <summary>
/// MPJ_3747_AltVendorPayee 06/03/2021 Nathan Ciantar
