    /// <summary>
    /// MPJ_15748_VendorList
    /// </summary>
    /// <returns>
    /// returns email address of the vendor 
    /// </returns>
    [SysClientCacheDataMethodAttribute(true)]
    public  display LogisticsElectronicAddressLocator displayMETEmailAddress()
    {
        DirPartyLocation           metDirPartyLocation;
        LogisticsElectronicAddress metLogisticsElectronicAddress;
       

        select firstonly  metDirPartyLocation
                    where metDirPartyLocation.party ==  this.Party
            join   metLogisticsElectronicAddress
                    where metLogisticsElectronicAddress.Location == metDirPartyLocation.Location
            && metLogisticsElectronicAddress.Type == LogisticsElectronicAddressMethodType::Email
            && metLogisticsElectronicAddress.IsPrimary == NoYes::Yes;
        
     
        return metLogisticsElectronicAddress.Locator;

    }
